#include <algorithm>
#include <numeric>
#include <iostream>

int main() {
    int coll[] = { 10, 20, 30, 40 };
    const size_t N = sizeof(coll) / sizeof(coll[0]);

    // Correct non-invasive range definition: [coll, coll + N)
    long sum = std::accumulate(coll, coll + N, 0L);

    std::cout << "Sum: " << sum << std::endl; // Output: 100

    // Pitfall: Incorrectly calculating the end pointer
    // std::sort(coll, coll + 40); // UB: Accesses out of bounds
}
